WITH q AS (SELECT COUNT(*) FROM public.registration r INNER JOIN public.event e ON r.event_id=e.event_id INNER JOIN public.organization o ON e.organization_id=o.organization_id WHERE r.account_id=1 AND r.status='active' AND e.status<>'deleted' AND o.status='active' AND o.organization_name ILIKE '%%') SELECT jsonb_build_object('rows',count(*),'md5',md5(COALESCE(string_agg(to_jsonb(q)::text,E'\n' ORDER BY to_jsonb(q)::text),''))) FROM q;
